import{_ as n,o as e,c as s,a2 as l}from"./chunks/framework.XXezeKOl.js";const d=JSON.parse('{"title":"Reflexion","description":"精读 Reflexion：不更新模型参数，而是让 Agent 用自然语言总结失败教训并写入记忆，在下一次尝试中改进。","frontmatter":{"title":"Reflexion","description":"精读 Reflexion：不更新模型参数，而是让 Agent 用自然语言总结失败教训并写入记忆，在下一次尝试中改进。"},"headers":[],"relativePath":"papers/reflexion.md","filePath":"papers/reflexion.md","lastUpdated":null}'),t={name:"papers/reflexion.md"};function i(r,a,o,p,u,c){return e(),s("div",null,[...a[0]||(a[0]=[l(`<h1 id="reflexion" tabindex="-1">Reflexion <a class="header-anchor" href="#reflexion" aria-label="Permalink to &quot;Reflexion&quot;">​</a></h1><h2 id="论文信息" tabindex="-1">论文信息 <a class="header-anchor" href="#论文信息" aria-label="Permalink to &quot;论文信息&quot;">​</a></h2><ul><li>标题：Reflexion: Language Agents with Verbal Reinforcement Learning</li><li>作者：Noah Shinn、Federico Cassano、Edward Berman、Ashwin Gopinath、Karthik Narasimhan、Shunyu Yao</li><li>年份：2023（NeurIPS 2023）</li><li>链接：<a href="https://arxiv.org/abs/2303.11366" target="_blank" rel="noreferrer">arXiv:2303.11366</a></li></ul><h2 id="一句话总结" tabindex="-1">一句话总结 <a class="header-anchor" href="#一句话总结" aria-label="Permalink to &quot;一句话总结&quot;">​</a></h2><p>Agent 失败后，让模型用自然语言写一段&quot;反思&quot;，说明哪里做错了、下次该怎么做，把这段反思存进记忆并放进下一次尝试的上下文，从而在不微调模型的情况下实现&quot;从试错中学习&quot;。</p><h2 id="要解决的问题" tabindex="-1">要解决的问题 <a class="header-anchor" href="#要解决的问题" aria-label="Permalink to &quot;要解决的问题&quot;">​</a></h2><p>传统强化学习让 Agent 从失败中学习，需要大量试错样本和昂贵的参数更新，对大模型来说几乎不现实。而像 <a href="/papers/react">ReAct</a> 这样的 Agent，每次尝试都是从零开始，上一次犯过的错误，下一次还会再犯。</p><p>作者的问题是：能不能把&quot;奖励信号&quot;转化成模型能读懂的语言反馈，让 Agent 在几次尝试之内就改进行为？</p><h2 id="核心方法" tabindex="-1">核心方法 <a class="header-anchor" href="#核心方法" aria-label="Permalink to &quot;核心方法&quot;">​</a></h2><p>Reflexion 由三个角色组成，都可以由大模型扮演：</p><ul><li><strong>Actor（执行者）：</strong> 根据任务和记忆生成行动，比如一个 ReAct Agent 或代码生成器。</li><li><strong>Evaluator（评估者）：</strong> 判断这次尝试是否成功。可以是环境给的二值信号、单元测试结果、启发式规则，或者另一个模型的判断。</li><li><strong>Self-Reflection（反思者）：</strong> 读取失败的轨迹和评估结果，生成一段自然语言的反思，写入长期记忆。</li></ul><div class="language-text vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>           ┌──────────────────────────────────────┐</span></span>
<span class="line"><span>           │          长期记忆（反思列表）           │</span></span>
<span class="line"><span>           │ &quot;上次我没检查抽屉就下结论，应该先……&quot;     │</span></span>
<span class="line"><span>           └──────────────────────────────────────┘</span></span>
<span class="line"><span>               │ 读取                    ▲ 写入</span></span>
<span class="line"><span>               ▼                         │</span></span>
<span class="line"><span>  任务 ──▶ ┌─────────┐   轨迹   ┌───────────┐  结果  ┌──────────────┐</span></span>
<span class="line"><span>           │  Actor  │ ───────▶ │ Evaluator │ ─────▶ │ Self-Reflect │</span></span>
<span class="line"><span>           └─────────┘          └───────────┘        └──────────────┘</span></span>
<span class="line"><span>               ▲                      │</span></span>
<span class="line"><span>               │                      │ 成功</span></span>
<span class="line"><span>               │                      ▼</span></span>
<span class="line"><span>               │                   结束</span></span>
<span class="line"><span>               └──── 失败：带着新的反思重新尝试 ────┘</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br><span class="line-number">4</span><br><span class="line-number">5</span><br><span class="line-number">6</span><br><span class="line-number">7</span><br><span class="line-number">8</span><br><span class="line-number">9</span><br><span class="line-number">10</span><br><span class="line-number">11</span><br><span class="line-number">12</span><br><span class="line-number">13</span><br><span class="line-number">14</span><br></div></div><p>关键在于反思的内容不是泛泛的&quot;我做错了&quot;，而是具体的、可执行的改进建议。记忆有容量上限，只保留最近几条反思，以控制上下文长度。</p><h2 id="关键实验结论" tabindex="-1">关键实验结论 <a class="header-anchor" href="#关键实验结论" aria-label="Permalink to &quot;关键实验结论&quot;">​</a></h2><p>论文在三类任务上做了实验：文本环境中的决策任务（ALFWorld）、多跳问答推理（HotpotQA）和编程（HumanEval 等代码生成基准，以及作者新建的一个高难度编程题集）。</p><ul><li><strong>决策任务：</strong> 加入 Reflexion 后，ReAct Agent 在多次尝试中的成功率持续上升，而不加反思的基线很快停滞。反思尤其能帮助 Agent 摆脱重复同一错误的循环。</li><li><strong>推理任务：</strong> 反思同样能提升问答的正确率，即使评估信号只是简单的&quot;答对 / 答错&quot;。</li><li><strong>编程任务：</strong> 让模型先自己生成单元测试，再根据测试结果反思和修改代码，在代码生成基准上取得了当时很好的成绩，超过了直接使用同一基座模型的结果。</li><li><strong>消融实验：</strong> 只做&quot;重试&quot;而不写反思，或者只给评估结果而不总结教训，效果都不如完整的 Reflexion，说明&quot;用语言总结经验&quot;本身是有效的。</li></ul><h2 id="对-agent-开发的启发" tabindex="-1">对 Agent 开发的启发 <a class="header-anchor" href="#对-agent-开发的启发" aria-label="Permalink to &quot;对 Agent 开发的启发&quot;">​</a></h2><ul><li><strong>评估信号决定反思质量。</strong> 编程任务效果好，很大程度上是因为单元测试提供了明确、可靠的反馈。设计 Agent 时，先想清楚&quot;怎么判断这一步做对了&quot;，比优化提示词更重要。</li><li><strong>反思是一种特殊的记忆。</strong> 把&quot;经验教训&quot;存下来并在后续任务中使用，是长期记忆的一种实用形式，详见 <a href="/guide/08-memory/memory-types">记忆的分类</a>。</li><li><strong>自我检查可以低成本地加进 Agent 循环。</strong> 在 Agent 给出最终结果前，加一步&quot;检查是否满足要求，不满足就修改&quot;，往往能提升质量，参考 <a href="/guide/06-agent-loop/reflection">Reflection 自我反思</a>。</li><li><strong>要设置重试上限。</strong> 反思会多次调用模型，成本随尝试次数增加，必须配合 <a href="/guide/06-agent-loop/stop-budget">预算控制</a>。</li></ul><h2 id="局限性" tabindex="-1">局限性 <a class="header-anchor" href="#局限性" aria-label="Permalink to &quot;局限性&quot;">​</a></h2><ul><li>依赖可靠的评估器。如果评估信号本身不准，比如模型自己生成的测试有错，反思可能会把 Agent 带向错误方向。</li><li>依赖模型的自我诊断能力。模型不一定能正确找出失败原因，可能&quot;反思&quot;出错误的结论。</li><li>需要允许多次尝试的环境。很多真实场景（发邮件、下单、改数据库）没有重来的机会。</li><li>记忆只保留有限几条反思，经验无法在大量任务间长期积累和泛化。</li><li>多次尝试带来成倍的延迟和成本。</li></ul><h2 id="相关文章" tabindex="-1">相关文章 <a class="header-anchor" href="#相关文章" aria-label="Permalink to &quot;相关文章&quot;">​</a></h2><ul><li><a href="/guide/06-agent-loop/reflection">Reflection 自我反思</a></li><li><a href="/guide/06-agent-loop/react">ReAct：推理与行动</a></li><li><a href="/guide/08-memory/memory-types">记忆的分类</a></li><li><a href="/guide/06-agent-loop/stop-budget">终止条件、步数与预算控制</a></li><li><a href="/guide/14-evaluation/llm-judge">LLM-as-Judge</a></li></ul>`,22)])])}const g=n(t,[["render",i]]);export{d as __pageData,g as default};
